#!/usr/bin/env node
// provision CLI — fill the accounts.db queue with capcut.com rows.
//
//     node bin/provision.js 20        # add 20 rows (username u+10hex,
//                                     #   email <username>@<EMAIL_DOMAIN>,
//                                     #   status 'unregistered')
//     node bin/provision.js --stats   # print queue statistics
//
// Mirrors gen-accounts.mjs UX: prints added/skipped + total + next-up
// username. Credentials (username/password) are generated by src/infra/db.js
// following the repo GitHub-account rule and never leave accounts.db; the
// signup engine only ever CONSUMES rows from this queue.

import { pathToFileURL } from 'node:url';
import { loadEnv, parseCli } from '../src/util/util.js';
import {
  openAccountsDb, ensureCapcutColumns, provisionCapcutAccounts, capcutStats,
} from '../src/infra/db.js';

const USAGE = `Usage: node bin/provision.js <N>
       node bin/provision.js --stats

  <N>        add N new capcut.com rows to the account queue
             (username u+10hex, password Vt-…-9x!K, email <username>@<EMAIL_DOMAIN>,
              status 'unregistered')
  --stats    print queue statistics and exit
  --help     show this help
`;

// CLI entry: N rows into the queue, or --stats. Exits 2 on a bad N / missing
// config, 0 otherwise.
async function main() {
  const flags = parseCli({
    options: {
      stats: { type: 'boolean', default: false },
      help: { type: 'boolean', default: false },
    },
    usage: 'node bin/provision.js <N> | node bin/provision.js --stats',
  });
  if (flags.help) {
    console.log(USAGE);
    return 0;
  }

  let cfg;
  try {
    cfg = await import('../config.js');
  } catch {
    console.error('config.js not found — copy config.example.js to node/config.js first.');
    return 2;
  }
  const settings = {};
  for (const k of Object.keys(cfg)) {
    if (/^[A-Z][A-Z0-9_]*$/.test(k)) settings[k] = cfg[k];
  }

  if (flags.stats) {
    const db = openAccountsDb(settings.ACCOUNTS_DB || '');
    try {
      ensureCapcutColumns(db);
      const st = capcutStats(db);
      console.log(`capcut.com queue: ${st.unregistered} unregistered / ${st.inFlight} in-flight`
        + ` / ${st.registered} registered / ${st.poisoned} poisoned (${st.total} total)`);
      return 0;
    } finally {
      db.close();
    }
  }

  // N must be a positive integer (refuse 0/negative/garbage) — checked BEFORE
  // any DB access so a misuse run has zero side effects.
  const raw = String(flags._[0] ?? '');
  const n = Number.parseInt(raw, 10);
  if (!Number.isInteger(n) || n <= 0) {
    console.error(`N must be a positive integer, got: ${raw || '(missing)'}`);
    console.error(USAGE);
    return 2;
  }

  const domain = settings.EMAIL_DOMAIN;
  if (!domain) {
    console.error('EMAIL_DOMAIN is not set in config.js.');
    return 2;
  }

  const db = openAccountsDb(settings.ACCOUNTS_DB || '');
  try {
    ensureCapcutColumns(db);
    const { added, skipped } = provisionCapcutAccounts(db, n, { emailDomain: domain });
    const total = capcutStats(db).total;
    // gen-accounts.mjs output shape, queue-scoped to capcut.com rows.
    console.log(`provisioned ${added} rows @${domain} (${skipped} existed) — ${total} capcut.com rows total`);
    const next = db.prepare(
      "SELECT username FROM accounts WHERE site='capcut.com' AND status='unregistered'"
      + ' ORDER BY created, rowid LIMIT 1').get();
    console.log(`next up: ${next ? next.username : '(none)'}`);
    return 0;
  } finally {
    db.close();
  }
}

// Run only when executed directly; importing stays side-effect free.
// loadEnv() first, per the CLI convention.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  loadEnv();
  main().then(
    (code) => process.exit(code ?? 0),
    (err) => {
      console.error(err && err.stack ? err.stack : String(err));
      process.exit(1);
    },
  );
}
